using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Text;
public static class MclaMixedLongSessionNative{
  public struct RECT{public int Left,Top,Right,Bottom;}public struct POINT{public int X,Y;}[StructLayout(LayoutKind.Sequential)]public struct IO{public ulong ReadOperationCount,WriteOperationCount,OtherOperationCount,ReadTransferCount,WriteTransferCount,OtherTransferCount;}
  delegate bool E(IntPtr h,IntPtr p);[DllImport("user32.dll")]static extern bool EnumWindows(E c,IntPtr p);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint p);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder s,int n);[DllImport("user32.dll")]static extern bool GetClientRect(IntPtr h,out RECT r);[DllImport("user32.dll")]static extern bool ClientToScreen(IntPtr h,ref POINT p);[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]public static extern IntPtr GetForegroundWindow();[DllImport("user32.dll")]static extern bool BringWindowToTop(IntPtr h);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int c);[DllImport("user32.dll")]static extern IntPtr SetFocus(IntPtr h);[DllImport("user32.dll")]static extern bool AttachThreadInput(uint attach,uint attachTo,bool value);[DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("kernel32.dll",SetLastError=true)]public static extern bool GetProcessIoCounters(IntPtr h,out IO c);
