function Safe([string]$Path,[string]$Description,[switch]$Exists){$full=[IO.Path]::GetFullPath($Path);$prefix=$repo.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description escapes repository."};$cursor=$repo;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object Length)){$cursor=Join-Path $cursor $part;if((Test-Path -LiteralPath $cursor)-and((Get-Item -LiteralPath $cursor -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)){throw "$Description traverses a reparse point."}};if($Exists-and-not(Test-Path -LiteralPath $full)){throw "$Description is missing."};$full}
function Hash([string]$Path){$stream=[IO.File]::OpenRead((Safe $Path 'Hash source' -Exists));$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','')}finally{$sha.Dispose();$stream.Dispose()}}
function Tree([string]$Root){$sha=[Security.Cryptography.SHA256]::Create();try{$files=@(Get-ChildItem -LiteralPath $Root -File -Recurse -Force|Sort-Object FullName);$bytes=0L;foreach($file in $files){$rel=$file.FullName.Substring($Root.TrimEnd('\').Length+1).Replace('\','/');$line=[Text.Encoding]::UTF8.GetBytes("$rel`t$($file.Length)`t$(Hash $file.FullName)`n");$null=$sha.TransformBlock($line,0,$line.Length,$line,0);$bytes+=$file.Length};$null=$sha.TransformFinalBlock([byte[]]::new(0),0,0);[ordered]@{sha256=([BitConverter]::ToString($sha.Hash)).Replace('-','');files=$files.Count;bytes=$bytes}}finally{$sha.Dispose()}}
function Game([string]$Root){$verified=&$gameVerifier -GamePath $Root;$manifest=Get-Content -LiteralPath $verified.ManifestPath -Raw|ConvertFrom-Json;$hashes=0;foreach($entry in @($manifest.Files)){$candidate=Join-Path $Root ([string]$entry.Path).Replace('/','\');if((Hash $candidate)-cne([string]$entry.Sha256).ToUpperInvariant()){throw "Source-game hash drifted for '$($entry.Path)'."};$hashes++};if($hashes-ne[int]$verified.FileCount){throw 'Source-game hash coverage is incomplete.'};[ordered]@{file_count=[int]$verified.FileCount;payload_bytes=[long]$verified.PayloadBytes;source_iso_sha256=[string]$verified.SourceIsoSha256}}
function Artifacts([string]$Root){@($artifactNames|ForEach-Object{[ordered]@{name=$_;sha256=(Hash (Join-Path $Root $_))}})}
function ArgQuote([string]$Value){'"'+$Value.Replace('"','\"')+'"'}
function WriteJson([string]$Path,$Value){[IO.File]::WriteAllText($Path,((ConvertTo-Json $Value -Depth 15)+[Environment]::NewLine),$utf8)}
function ReadLogs([string]$Root){$text='';foreach($file in @(Get-ChildItem -LiteralPath $Root -File -Filter 'mcla*.log' -ErrorAction SilentlyContinue|Sort-Object Name)){try{$stream=[IO.File]::Open($file.FullName,'Open','Read','ReadWrite');try{$reader=[IO.StreamReader]::new($stream);try{$text+=$reader.ReadToEnd()}finally{$reader.Dispose()}}finally{$stream.Dispose()}}catch{}};$text}
function WaitMarker([Diagnostics.Process]$Process,[string]$Root,[string]$Marker,[int]$Seconds){$deadline=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$deadline){if($Process.HasExited){throw "Process exited before startup marker '$Marker'."};if((ReadLogs $Root).Contains($Marker)){return};Start-Sleep -Milliseconds 200};throw "Startup marker timed out: $Marker"}
function ReadProcessAwareExact([Diagnostics.Process]$Process,[string]$Prompt,[string]$Exact){try{$null=[Console]::KeyAvailable}catch{throw 'Interactive console input is unavailable; run this script in a visible console.'};while($true){Write-Host ($Prompt+"`nType exactly: $Exact`: ") -ForegroundColor Yellow -NoNewline;$input=[Text.StringBuilder]::new();while($true){if($Process.HasExited){Write-Host;throw "Process exited while waiting for '$Exact' (exit $($Process.ExitCode))."};if(-not[Console]::KeyAvailable){Start-Sleep -Milliseconds 50;continue};$key=[Console]::ReadKey($true);if($key.Key-eq[ConsoleKey]::Enter){Write-Host;break};if($key.Key-eq[ConsoleKey]::Backspace){if($input.Length){$input.Length--;Write-Host "`b `b" -NoNewline};continue};if(-not[char]::IsControl($key.KeyChar)){$null=$input.Append($key.KeyChar);Write-Host $key.KeyChar -NoNewline}};if($input.ToString()-ceq$Exact){return};Write-Host 'Ignored; the exact phrase is required and the game remains running.' -ForegroundColor DarkYellow}}
function ExactWindow([Diagnostics.Process]$Process){$hits=@();foreach($handle in [MclaMixedLongSessionNative]::Handles($Process.Id)){if([regex]::IsMatch([MclaMixedLongSessionNative]::Title($handle),'^mcla \[rexglue-v[^\]]+\]$')){$hits+=$handle}};if($hits.Count-ne1){throw 'Exact visible MCLA window was not found.'};$hits[0]}
function CloseExact([Diagnostics.Process]$Process){if(-not[MclaMixedLongSessionNative]::PostMessage((ExactWindow $Process),0x10,[IntPtr]::Zero,[IntPtr]::Zero)){throw 'Exact PID/window WM_CLOSE failed.'}}
function Capture([Diagnostics.Process]$Process,[string]$Path,[int]$Checkpoint,[long]$Elapsed,[switch]$Required){
  if($Process.HasExited){throw "Process exited before capture $Checkpoint (exit $($Process.ExitCode))."}
  $scheduled=[long]$Checkpoint*900
  try{
    $handle=ExactWindow $Process
    $deadline=[DateTime]::UtcNow.AddSeconds($(if($Required){20}else{2}))
    do{
      if($Required){$null=[MclaMixedLongSessionNative]::FocusWindow($handle);Start-Sleep -Milliseconds 250}
      elseif([MclaMixedLongSessionNative]::GetForegroundWindow()-ne$handle){return [ordered]@{status='skipped';checkpoint=$Checkpoint;scheduled_elapsed_seconds=$scheduled;attempted_elapsed_seconds=$Elapsed;reason='mcla-window-not-foreground'}}
      if([MclaMixedLongSessionNative]::GetForegroundWindow()-ne$handle){continue}
      Start-Sleep -Milliseconds 250
      $r=[MclaMixedLongSessionNative]::Client($handle)
      if($r.Count-ne4-or$r[2]-lt640-or$r[3]-lt360){if($Required){throw 'MCLA client geometry is invalid.'};return [ordered]@{status='skipped';checkpoint=$Checkpoint;scheduled_elapsed_seconds=$scheduled;attempted_elapsed_seconds=$Elapsed;reason='invalid-client-geometry'}}
      $source=[Drawing.Bitmap]::new($r[2],$r[3])
      try{$g=[Drawing.Graphics]::FromImage($source);try{$g.CopyFromScreen($r[0],$r[1],0,0,[Drawing.Size]::new($r[2],$r[3]))}finally{$g.Dispose()};$bmp=[Drawing.Bitmap]::new(1280,720);try{$g2=[Drawing.Graphics]::FromImage($bmp);try{$g2.DrawImage($source,0,0,1280,720)}finally{$g2.Dispose()};$bmp.Save($Path,[Drawing.Imaging.ImageFormat]::Bmp)}finally{$bmp.Dispose()}}finally{$source.Dispose()}
      $image=[Drawing.Bitmap]::FromFile($Path)
      try{$bins=New-Object 'Collections.Generic.HashSet[int]';for($y=0;$y-lt720;$y+=12){for($x=0;$x-lt1280;$x+=12){$c=$image.GetPixel($x,$y);$null=$bins.Add((($c.R-shr3)-shl10)-bor(($c.G-shr3)-shl5)-bor($c.B-shr3))}}}finally{$image.Dispose()}
      if($bins.Count-ge80){return [ordered]@{status='captured';checkpoint=$Checkpoint;scheduled_elapsed_seconds=$scheduled;attempted_elapsed_seconds=$Elapsed;name=(Split-Path $Path -Leaf);elapsed_seconds=$Elapsed;sha256=(Hash $Path);bytes=[long](Get-Item -LiteralPath $Path).Length;color_bins=$bins.Count}}
      Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
      Start-Sleep -Milliseconds 250
    }while([DateTime]::UtcNow-lt$deadline)
  }catch{if($Required){throw};Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue;return [ordered]@{status='skipped';checkpoint=$Checkpoint;scheduled_elapsed_seconds=$scheduled;attempted_elapsed_seconds=$Elapsed;reason='capture-error'}}
  if($Required){throw 'Exact MCLA window did not yield a nontrivial physical capture within 20 seconds.'}
  Remove-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
  [ordered]@{status='skipped';checkpoint=$Checkpoint;scheduled_elapsed_seconds=$scheduled;attempted_elapsed_seconds=$Elapsed;reason='nontrivial-frame-unavailable'}
}
function Sample([Diagnostics.Process]$Process,[int]$Checkpoint,[long]$Elapsed){if($Process.HasExited){throw 'Process exited during resource sampling.'};$Process.Refresh();$io=[MclaMixedLongSessionNative+IO]::new();if(-not[MclaMixedLongSessionNative]::GetProcessIoCounters($Process.Handle,[ref]$io)){throw 'GetProcessIoCounters failed.'};[ordered]@{checkpoint=$Checkpoint;elapsed_seconds=$Elapsed;private_bytes=[long]$Process.PrivateMemorySize64;working_set_bytes=[long]$Process.WorkingSet64;handle_count=[long]$Process.HandleCount;thread_count=[long]$Process.Threads.Count;io_read_bytes=[long]$io.ReadTransferCount}}
function RecoveryMessage([Diagnostics.Process]$Watcher,[string]$Archive,[string]$User){
  $fallback="No recovery snapshot was confirmed; inspect the working profile at '$User'."
  try{
    if(-not$Watcher-or-not$Watcher.HasExited-or$Watcher.ExitCode-ne0){return $fallback}
    $latestPath=Safe (Join-Path $Archive 'latest.json') 'Recovery latest snapshot' -Exists
    $latest=Get-Content -LiteralPath $latestPath -Raw|ConvertFrom-Json
    if($latest.schema-cne'mcla-soak-save-snapshot-v1'-or-not$latest.complete_profile_tree){return $fallback}
    $snapshot=Safe (Join-Path $Archive ([string]$latest.snapshot_directory)) 'Recovery snapshot' -Exists
    if((Split-Path $snapshot -Parent)-cne[IO.Path]::GetFullPath($Archive)){return $fallback}
    $manifestPath=Safe (Join-Path $snapshot 'snapshot.json') 'Recovery snapshot manifest' -Exists
    $manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json
    if((ConvertTo-Json $latest -Compress)-cne(ConvertTo-Json $manifest -Compress)-or(Hash (Join-Path $snapshot $saveRelative))-cne$latest.save_sha256-or(Hash (Join-Path $snapshot $headerRelative))-cne$latest.header_sha256){return $fallback}
    "Recovery save snapshot confirmed: '$snapshot'."
  }catch{$fallback}
}
function LatestSeed([string]$Root){
  $candidates=@()
  foreach($directory in @(Get-ChildItem -LiteralPath $Root -Directory -ErrorAction SilentlyContinue)){
    $latestPath=Join-Path $directory.FullName 'latest.json'
    if(-not(Test-Path -LiteralPath $latestPath)){continue}
    try{
      $manifest=Get-Content -LiteralPath $latestPath -Raw|ConvertFrom-Json
      if($manifest.schema-cne'mcla-soak-save-snapshot-v1'-or-not$manifest.complete_profile_tree){continue}
      $snapshot=Safe (Join-Path $directory.FullName ([string]$manifest.snapshot_directory)) 'Candidate snapshot' -Exists
      if((Split-Path $snapshot -Parent)-cne$directory.FullName){continue}
      $snapshotManifestPath=Safe (Join-Path $snapshot 'snapshot.json') 'Candidate snapshot manifest' -Exists
      $snapshotManifest=Get-Content -LiteralPath $snapshotManifestPath -Raw|ConvertFrom-Json
      if((ConvertTo-Json $manifest -Compress)-cne(ConvertTo-Json $snapshotManifest -Compress)){continue}
      if((Hash (Join-Path $snapshot $saveRelative))-cne$manifest.save_sha256-or(Hash (Join-Path $snapshot $headerRelative))-cne$manifest.header_sha256){continue}
      $candidates+=[pscustomobject]@{Captured=[DateTime]::Parse([string]$manifest.captured_utc).ToUniversalTime();Archive=$directory.FullName;Snapshot=$snapshot;Manifest=$manifest;Latest=$latestPath}
    }catch{}
  }
  if(-not$candidates.Count){throw 'No complete hash-verified M6-014 recovery snapshot exists.'}
  @($candidates|Sort-Object Captured -Descending)[0]
}
function Bounds($Samples){$first=$Samples[0];$last=$Samples[-1];[ordered]@{private_growth_bytes=[long]$last.private_bytes-[long]$first.private_bytes;working_growth_bytes=[long]$last.working_set_bytes-[long]$first.working_set_bytes;handle_growth=[long]$last.handle_count-[long]$first.handle_count;thread_growth=[long]$last.thread_count-[long]$first.thread_count;io_read_growth_bytes=[long]$last.io_read_bytes-[long]$first.io_read_bytes;private_peak_growth_bytes=[long](($Samples|ForEach-Object private_bytes|Measure-Object -Maximum).Maximum)-[long]$first.private_bytes;working_peak_growth_bytes=[long](($Samples|ForEach-Object working_set_bytes|Measure-Object -Maximum).Maximum)-[long]$first.working_set_bytes}}
